import sys

def is_consistent(s):
    n = len(s)
    # If all characters are 'E', it's always consistent
    if s == 'E' * n:
        return True
    # If there's an 'N' and the string is not all 'E', check for consistency
    for i in range(n):
        if s[i] == 'N':
            if s[(i + 1) % n] == 'N':
                return False
    return True

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        s = data[index]
        index += 1
        if is_consistent(s):
            results.append("YES")
        else:
            results.append("NO")

    print("\n".join(results))

if __name__ == "__main__":
    main()
